data.configure-workspace-root#Configure Works:
Init project by pnpm $ pnpm init --init-type module --init-package-manager Configure workspace. Edit package.json, { "private": true } and add a pnpm-workspace.yaml file to structure project following the best practices.
packages: - 'apps/*' - 'packages/*' Add shared dependencies. shared development dependencies: typescript, eslint, prettier $ pnpm i -D eslint -w $ pnpm i -D prettier eslint-config-prettier -w $ pnpm i -D typescript typescript-eslint -w Use turbo to manage monorepo $ pnpm add turbo --save-dev --workspace-root add a turbo.json file
{ "tasks": { "build": { "dependsOn": ["^build"], "outputs": ["dist/**", ".next/**", "!.next/cache/**"] }, "dev": { "cache": false, "persistent": true }, "lint": { "dependsOn": ["^lint"], "outputs": [] }, "lint:fix": { "dependsOn": ["^lint:fix"], "outputs": [], "cache": false }, "format": { "dependsOn": ["^format"], "outputs": [], "cache": false }, "format:check": { "dependsOn": ["^format:check"], "outputs": [], "cache": false }, "type-check": { "dependsOn": ["^type-check"] }, "test": { "dependsOn": ["^build"], "outputs": ["coverage/**"] }, "clean": { "cache": false } } } Configure scripts. Edit package.json file { "scripts": { "build": "turbo run build", "dev": "turbo run dev", "lint": "turbo run lint", "lint:fix": "turbo run lint:fix", "lint:root": "eslint . --fix", "format": "turbo run format", "format:check": "turbo run format:check", "type-check": "turbo run type-check", "clean": "turbo run clean", "test": "turbo run test" } }
